const C={ink:'#274654',line:'#7194a3',pale:'#f0f6f9',liquid:'#d7e7ee',gold:'#cfaa6c',red:'#bd5b53'};
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const tx=(x,y,s,z=17)=>`<text x="${x}" y="${y}" text-anchor="middle" font-family="Arial,sans-serif" font-size="${z}" fill="${C.ink}">${esc(s)}</text>`;
const line=(d,c=C.line,w=2)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const box=(x,y,w,h,f=C.pale)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="10" fill="${f}" stroke="${C.line}" stroke-width="1.6"/>`;
const arrow=(x,y,a=0)=>`<g transform="translate(${x} ${y}) rotate(${a})">${line('M-22 0H22M14 -7L22 0L14 7',C.line,2.5)}</g>`;
function wrap(s,m){const rows=[];let row='';for(const w of String(s).split(/\s+/)){if((row+' '+w).length>m){rows.push(row);row=w;}else row+=(row?' ':'')+w;}if(row)rows.push(row);return rows;}
const title=s=>wrap(s,47).map((s,i)=>tx(300,27+i*24,s,20)).join('');
const note=s=>wrap(s,74).map((s,i)=>tx(300,345+i*17,s,13)).join('');
const panel=(x,y,w,ss)=>box(x,y,w,ss.length*28+22)+ss.map((s,i)=>tx(x+w/2,y+28+i*28,s,16)).join('');
function tube(x,y,w=104,ox=true,qd=false){let s=box(x,y,w,34,'#a9c1cc')+line(`M${x+14} ${y+10}H${x+w-12}M${x+14} ${y+19}H${x+w-12}M${x+14} ${y+27}H${x+w-12}`)+`<ellipse cx="${x+12}" cy="${y+17}" rx="8" ry="12" fill="white" stroke="${C.line}"/>`;if(ox)for(const[a,b]of[[24,0],[w-9,10],[57,34]])s+=`<circle cx="${x+a}" cy="${y+b}" r="4" fill="${C.red}"/>`;if(qd)for(const[a,b]of[[24,-2],[w-4,20],[64,33]])s+=`<path d="M${x+a-10} ${y+b-10}l20 2l2 17l-19 3Z" fill="${C.gold}" stroke="#957642"/>`;return s;}
function beaker(x,y,{state='solution',label='',stir=false}={}){let s=`<path d="M${x-52} ${y-67}V${y+45}Q${x-52} ${y+59} ${x-38} ${y+59}H${x+38}Q${x+52} ${y+59} ${x+52} ${y+45}V${y-67}" fill="none" stroke="${C.line}" stroke-width="2.5"/><path d="M${x-49} ${y-14}H${x+49}V${y+42}Q${x+49} ${y+56} ${x+37} ${y+56}H${x-37}Q${x-49} ${y+56} ${x-49} ${y+42}Z" fill="${C.liquid}"/>`;if(['tubes','composite','purified-composite'].includes(state))s+=tube(x-37,y+6,74,true,state!=='tubes');if(state==='composite'||state==='precipitate')for(const[a,b]of[[-29,45],[22,44],[-16,25]])s+=`<circle cx="${x+a}" cy="${y+b}" r="5" fill="${C.gold}"/>`;if(state==='precipitate')s+=tube(x-35,y+19,70,true,true);if(stir)s+=line(`M${x-17} ${y+48}H${x+17}`,C.ink,5);return s+tx(x,y+85,label,16);}
const heater=(x,y)=>box(x-77,y,154,29,'#ead6b3')+line(`M${x-23} ${y+9}H${x+23}`, '#b28a4c',4);
const grid=(x,y)=>box(x-51,y-48,102,96,'#e6edf1')+[-30,-10,10,30].map(a=>line(`M${x+a} ${y-43}V${y+43}M${x-45} ${y+a}H${x+45}`,C.line,1)).join('');
function stage(o,r){const id=o.id,rid=r.record_id;let art='',notes='All apparatus dimensions and colors are illustrative; source omissions remain explicit.';
 if(id==='oxidize'){art=tube(35,175,125,false)+arrow(220,192)+beaker(362,181,{state:'tubes',label:'Oxygenated MWNTs'})+panel(225,72,350,['KMnO₄ / H₂SO₄ oxidation']);notes='Vigorous oxidative treatment follows the cited protocol. Reagent charges, acid concentration, temperature and duration are unreported; red sites illustrate expected surface oxygen, not a measured map.';}
 else if(id==='acid-hcl'||id==='acid-hf'){const hf=id==='acid-hf';art=panel(21,102,211,[hf?'10% HF solution':'35% HCl solution','Percentage basis unknown'])+arrow(281,182)+beaker(436,177,{state:'tubes',label:'Sequential acid treatment'});notes='The source reports successive hydrochloric-acid then hydrofluoric-acid treatment. Volumes, duration, treatment temperature and intermediate separation or rinsing are not specified.';}
 else if(id==='wash-tubes'){art=panel(22,118,214,['Distilled water','Extensive washing'])+arrow(284,184)+beaker(432,178,{state:'tubes',label:'Purified oxidized tubes'});notes='Extensive distilled-water washing follows acid treatment. No number of washes, wash volume, filtration apparatus or centrifuge settings are invented.';}
 else if(id==='dry-tubes'){art=box(51,106,264,205,'#dce7ec')+box(75,129,215,153,'#faf0de')+tube(120,192,123,true)+panel(355,116,220,['Drying oven','150 °C','Duration unreported']);notes='The processed nanotubes are heated at 150 °C in a drying oven. The article gives no drying duration or pressure; this condition is not transferred to final composite drying.';}
 else if(id==='mix-cd'){art=panel(16,102,245,['Oxidized MWNTs + CdO','TDPA + TOPO','Charges unreported'])+arrow(300,183)+beaker(453,183,{state:'tubes',label:'Pre-growth mixture'});notes='TDPA is described as substoichiometric, without a numerical ratio or reagent amounts. The nanotubes are present before crystal growth; no CdTe particles are drawn in this precursor mixture.';}
 else if(id==='heat'){art=beaker(188,164,{state:'tubes',stir:true,label:''})+heater(188,239)+tx(188,300,'Precursor coordination stage',16)+panel(350,107,223,['320 °C','Argon','Vigorous stirring']);notes='The MWNT/CdO/TDPA mixture is heated in TOPO under argon with vigorous stirring. Cadmium binding at oxygenated sites is the authors’ rationale, not a resolved molecular coordination structure.';}
 else if(id==='adjust'){art=beaker(181,168,{state:'tubes',label:'Pre-injection mixture'})+arrow(304,178)+panel(356,118,219,['320 → 300 °C','Injection at 300 °C']);notes='The source distinguishes the 320 °C precursor-heating condition from injection at 300 °C. Adjustment time, cooling equipment and numeric ramp are not reported.';}
 else if(id==='injection'){art=box(72,78,185,76,C.liquid)+tx(164,109,'Te solution in TOP',17)+tx(164,136,'Dose unreported',15)+arrow(247,182,44)+beaker(351,205,{state:'tubes',label:'Injection at 300 °C'})+tx(496,105,'TOP solvent',17);notes='Inject the source-named tellurium solution in TOP. The illustration does not invent elemental-Te addition, an exact TOPTe molecule, syringe hardware, injection rate or delivered volume.';}
 else if(id==='grow'){art=beaker(190,164,{state:'composite',stir:true,label:''})+heater(190,239)+tx(190,302,'Attached and free nanocrystals',16)+panel(357,116,215,['250 °C','20 min growth']);notes='Growth produces nanotube-associated CdTe together with free particles later removed in workup. Particle positions and sizes in the diagram are explanatory, not a source size distribution.';}
 else if(id==='stop'){art=beaker(155,163,{state:'composite',label:'Reaction mixture'})+arrow(293,190)+heater(447,219)+tx(445,293,'Remove heating source',17);notes='After twenty minutes of growth, the heating source is removed. This is cessation of heating, not addition of an unspecified chemical quench.';}
 else if(id==='cool'){art=beaker(183,173,{state:'composite',label:'Cooling mixture'})+panel(355,120,218,['Cool to 50 °C','Rate unreported']);notes='Toluene addition follows cooling to 50 °C. No cooling bath, coolant, duration or rate is described.';}
 else if(id==='solvate'){art=panel(23,104,207,['Toluene','5 mL','At 50 °C'])+arrow(280,186)+beaker(430,181,{state:'composite',label:'Diluted reaction mixture'});notes='Five millilitres of toluene is the specified workup addition. It does not supply the reaction volume or the later toluene wash volume.';}
 else if(id==='precipitate'){art=panel(22,107,219,['Methanol addition','Volume unreported'])+arrow(289,186)+beaker(435,179,{state:'precipitate',label:'Composite + free CdTe solids'});notes='Methanol initiates precipitation. The solid residue contains functionalized nanotubes and unattached CdTe; precipitation is not a reported centrifugation step.';}
 else if(id==='filter'||id==='wash'){const wash=id==='wash';art=panel(25,92,241,wash?['Copious toluene','Wash membrane residue']:['Precipitated solid residue','Composite + free CdTe'])+arrow(296,156)+line('M339 146L383 218H470L513 146')+box(374,215,104,16,'#c3d7df')+tube(385,179,75,true,true)+line('M414 232V282H446V232')+tx(433,319,'0.2 µm PTFE membrane',16);if(wash)art+=`<circle cx="425" cy="250" r="5" fill="${C.gold}"/><circle cx="439" cy="276" r="5" fill="${C.gold}"/>`;else art+=`<circle cx="472" cy="209" r="5" fill="${C.gold}"/>`;notes=wash?'Toluene washing removes unattached CdTe while nanotube heterostructures remain on the membrane. The volume is qualitative; do not label the washed-away fraction as the retained composite.':'Filter the precipitated residue over the membrane. The source initially retains both composite and free CdTe; purification occurs in the following toluene wash, not by an invented selective filtration.';}
 else if(id==='final-dry'){art=tube(95,168,130,true,true)+arrow(298,189)+tube(395,168,130,true,true)+panel(172,82,266,['Dry retained heterostructures']);notes='The membrane-retained heterostructures are dried for characterization. Final drying time, temperature, pressure and atmosphere are unreported; the upstream 150 °C nanotube treatment is not reused.';}
 else if(rid.endsWith('electron-microscopy')){
  if(id==='disperse'){art=panel(21,112,219,['Ethanol','Sample droplets'])+arrow(288,184)+beaker(433,178,{state:'purified-composite',label:'Microscopy dispersion'});notes='TEM/HRTEM samples come from ethanolic sample droplets. Dispersion concentration and sonication conditions are not supplied; this is specimen preparation, not synthesis.';}
  if(id==='deposit'){art=beaker(142,165,{state:'purified-composite',label:'Ethanolic droplet'})+arrow(291,184)+grid(431,190)+tx(431,291,'300 mesh Cu / lacey carbon',16);notes='Dry a sample droplet on a 300 mesh copper grid carrying lacey carbon film. Droplet volume and drying conditions are not reported.';}
  if(id==='image-tem'||id==='image-hrtem'){const hr=id==='image-hrtem';art=box(126,91,107,69)+arrow(179,192,90)+grid(179,267)+panel(350,105,226,hr?['JEOL 2010F HRTEM','200 kV','Oxford INCA EDS']:['Philips CM12 TEM','120 kV','EDAX capabilities']);notes='Original microscopy retains each panel’s specimen and scale bar. Electron-beam voltage and detector capabilities are acquisition settings; no atomic-coordinate model or same-particle tracking is inferred.';}
 }
 else if(rid.endsWith('sem')){
  if(id==='deposit'){art=grid(185,176)+box(94,245,183,17,'#bcced7')+tx(185,293,'Cu grid over Be plate',17)+panel(354,113,217,['Drop-dried sample','Homemade holder']);notes='SEM samples are drop-dried onto copper grids and held over a beryllium plate. The SEM subsection does not restate an ethanol solvent, grid mesh or coating, so these are not inherited from TEM.';}
  if(id==='image'){art=box(112,93,112,66)+arrow(196,191,57)+grid(242,261)+panel(355,109,214,['Leo 1550 field emission','2–10 kV','Working distance 2 mm']);notes='SEM settings belong to imaging. Individual panel voltages and detector settings are not supplied; source scale bars remain attached to the original panels.';}
 }
 else if(rid.endsWith('eds')){art=grid(162,217)+arrow(285,175,-25)+panel(354,105,218,['Energy-dispersive X-rays','Cd / Te / P discussion','Caption unit conflict']);notes='Figure 4a inset supplies an EDS trace. The caption says energy in eV despite its 0–10 scale; preserve the original axis and uncertainty rather than silently assigning calibrated energies or atomic percentages.';}
 else if(rid.endsWith('xps')){
  if(id==='mount'){art=box(72,198,221,41,'#a9bec8')+box(90,184,186,13,'#8aa6b4')+tube(123,148,112,true,true)+panel(353,108,221,['Stainless-steel holder','Conductive double-sided tape']);notes='Attach the specimen to a steel holder with conductive tape. This mounting support is not a synthesis precursor or measured final material component.';}
  if(id==='evacuate'){art=box(68,113,239,177,'#e1ebef')+tube(133,197,105,true,true)+line('M307 205H338')+panel(355,113,219,['DS800 XPS chamber','Base ≈5 × 10⁻⁹ Torr']);notes='The reported base pressure is an XPS chamber condition. It is not the reaction or drying pressure; pumping time is unknown.';}
  if(id==='survey'||id==='high-resolution'){const high=id==='high-resolution';art=panel(21,115,189,['Mg Kα X-rays'])+arrow(269,184)+tube(337,179,109,true,true)+panel(260,70,313,high?['Pass energy 10 eV · step 0.1 eV']:['Pass energy 80 eV · step 0.75 eV']);notes='A hemispherical analyzer detects photoelectrons. Survey and high-resolution acquisition settings remain separate; the source does not provide a calibration recipe or complete fitted-component parameters.';}
 }
 else if(rid.endsWith('xrd')){art=panel(20,105,163,['Cu Kα radiation','λ = 1.54 Å'])+arrow(232,182,25)+tube(278,233,99,true,true)+arrow(421,178,-25)+tx(493,113,'Scintag',18)+tx(487,151,'Bragg geometry',16);notes='Powder diffraction supports predominantly wurtzite CdTe with possible zinc-blende contributions/stacking faults and MWNT peaks. No refined structure or quantitative phase fractions are supplied.';}
 else if(rid.endsWith('uv-visible')){
  if(id==='dissolve-washings'){art=panel(23,113,219,['Free CdTe washings','Toluene'])+arrow(291,184)+beaker(432,176,{label:'Optical comparison solution'});notes='The washed-away CdTe is measured in toluene. It is separate from the nanotube composite and from the no-tube reference described in discussion; concentration is unspecified.';}
  if(id==='disperse-composite'){art=beaker(181,164,{state:'purified-composite',label:'CdTe / MWNT in DMF'})+box(100,255,162,33)+panel(351,109,221,['Sonication','Time / power unknown']);notes='The heterostructure is dispersed by sonication in DMF for UV-visible analysis. Sonication is not a synthesis growth stage; its duration and power are not supplied.';}
  if(id==='acquire'){art=panel(18,108,188,['Thermospectronics UV1'])+arrow(257,183)+box(316,137,59,117,C.liquid)+arrow(426,183)+tx(506,168,'Quartz cell',17)+tx(505,201,'10 mm path',17);notes='Original electronic spectra compare the heterostructure and washings. No resolved composite CdTe exciton is reported; missing raw curves, optical density and concentrations remain missing.';}
 }
 else if(rid.endsWith('infrared')){art=tube(104,157,139,true)+box(92,205,160,38,'#b8d2dd')+arrow(296,187)+panel(354,106,222,['ThermoNicolet Nexus 670','ZnSe single-reflection ATR']);notes='The matched SI infrared spectrum belongs to oxidized MWNT precursors. The paper gives no exact IR peak table or chemical-group assignments for that trace; it is not a composite spectrum.';}
 else if(rid.endsWith('raman')){art=panel(18,98,206,['785 nm diode laser','10 mW'])+arrow(273,178)+tube(346,205,126,true,true)+panel(301,73,279,['Jasco Ventuno · aperture 200 µm']);notes='Raman compares oxidized MWNTs with the CdTe/MWNT composite. Reported 166 cm⁻¹, G and D bands retain their specimen scope; laser power is not intensity without an illuminated area.';}
 return art?{art,notes,heading:o.label}:null;
}
export function buildBanerjee2003Scene(o,r){if(r?.lineage?.source_group!=='banerjee2003'||!r.record_id?.startsWith('banerjee-2003-'))return null;const s=stage(o,r);if(!s)return null;return{kind:r.record_id+'-'+o.id,svg:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 420" role="img" aria-label="${esc(o.label)} — explanatory apparatus" style="width:100%;height:auto"><title>${esc(o.label)}</title><desc>Source-specific nanotube processing, nanocrystal growth, fraction separation and analytical operation. Apparatus and specimen cartoons are illustrative, not measured atomic structures or experimental data.</desc>${title(s.heading)}${s.art}${note(s.notes)}</svg>`,caption:'Source-specific scientific schematic. Tube geometry, particle placement and colors are illustrative; preparation stages and retained fractions follow the reviewed source.'};}
export function createBanerjee2003Art(o,r){const s=buildBanerjee2003Scene(o,r);if(!s)return null;const d=document.createElement('div');d.className='protocol-art protocol-art-banerjee2003';d.dataset.scene='banerjee2003-'+s.kind;d.style.height='auto';d.innerHTML=s.svg;return d;}
